19	// runNormalizeFiltered parses emitted results like runNormalize while
20	// reporting the failure count the entry point returned.
21	func runNormalizeFiltered(t *testing.T, input string, filter *SourceCIDRFilter) ([]map[string]any, int) {
22		t.Helper()
23		var out bytes.Buffer
24		failures, err := NormalizeReaderFiltered(strings.NewReader(input), &out, filter)
25		if err != nil {
26			t.Fatalf("NormalizeReaderFiltered returned error: %v", err)
27		}
28		var results []map[string]any
29		dec := json.NewDecoder(bytes.NewReader(out.Bytes()))
30		for {
31			var m map[string]any
32			if err := dec.Decode(&m); err != nil {
33				if err == io.EOF {
34					break
35				}
36				t.Fatalf("decoding result: %v", err)
37			}
38			results = append(results, m)
39		}
40		if got := countFailures(results); got != failures {
41			t.Fatalf("NormalizeReaderFiltered returned %d failures but output shows %d", failures, got)
42		}
43		return results, failures
44	}
