76	// only a dotted decimal IPv4 address, a slash, and a 0-32 prefix length.
77	func TestParseSourceCIDRFilterRejects(t *testing.T) {
78		bad := []string{
79			"",
80			"192.0.2.0",       // no slash/length
81			"192.0.2.0/",      // empty length
82			"192.0.2.0/24/32", // extra segment
83			"192.0.2/24",      // too few octets
84			"192.0.2.0.1/24",  // too many octets
85			"192.0.2.0/33",    // prefix too large
86			"192.0.2.0/100",
87			"192.0.2.0/-1",  // negative length
88			"192.0.2.0/24x", // trailing junk
89			"256.0.0.0/8",   // octet out of range
90			"192.168.1.256/24",
91			"192.168.001.1/24", // leading-zero padding
92			"01.2.3.4/8",
93			"192.0.2.1/024", // padded length
94			"::1/128",       // IPv6 form
95			"::ffff:192.0.2.0/120",
96			"192.0.2.0/0x8", // non-decimal length
97			"abc",
98			"192.0.2.0/24 ", // trailing space
99			" 192.0.2.0/24",
100		}
101		for _, in := range bad {
102			if f, err := ParseSourceCIDRFilter(in); err == nil {
103				t.Fatalf("ParseSourceCIDRFilter(%q) must fail, got filter %s", in, f)
