108	// TestSourceCIDRFilterAdmitsNormalized checks the membership function
109	// against the exact strings that appear in normalized output.
110	func TestSourceCIDRFilterAdmitsNormalized(t *testing.T) {
111		block, err := ParseSourceCIDRFilter("192.0.2.123/24")
112		if err != nil {
113			t.Fatal(err)
114		}
115		host, err := ParseSourceCIDRFilter("192.0.2.1/32")
116		if err != nil {
117			t.Fatal(err)
118		}
119		all, err := ParseSourceCIDRFilter("0.0.0.0/0")
120		if err != nil {
121			t.Fatal(err)
122		}
123	
124		inside := []string{"192.0.2.0", "192.0.2.1", "192.0.2.123", "192.0.2.255"}
125		outside := []string{
126			"192.0.3.0", "198.51.100.1", "0.0.0.0", "255.255.255.255",
127			// Normalized genuine IPv6 sources never match an IPv4 network,
128			// even with the same trailing 32 bits or a v6-mapped spelling
129			// written from outside normalization.
130			"::c000:201", "::192.0.2.1", "2001:db8::1", "::1",
131		}
