165	// TestSourceCIDRFilterMappedEquivalence pins the headline equivalence:
166	// 192.0.2.1 and ::ffff:192.0.2.1 normalize to the same source and therefore
167	// filter identically, while ::192.0.2.1 stays IPv6 and does not.
168	func TestSourceCIDRFilterMappedEquivalence(t *testing.T) {
