193	// TestSourceCIDRFilterStreamBehavior covers the mixed stream: in-network
194	// successes are emitted, out-of-network / absent / IPv6 successes are
195	// dropped silently, blank and dropped lines must not renumber later lines,
196	// and failures survive regardless of their address.
197	func TestSourceCIDRFilterStreamBehavior(t *testing.T) {
198		filter, err := ParseSourceCIDRFilter("192.0.2.128/25") // 192.0.2.128 - 192.0.2.255
199		if err != nil {
200			t.Fatal(err)
201		}
202		input := strings.Join([]string{
203			`{"timestamp":"2026-01-02T00:00:00Z","action":"in-low-boundary","source_ip":"192.0.2.128"}`,   // line 1 admitted
204			`{"timestamp":"2026-01-02T00:00:00Z","action":"in-high-boundary","source_ip":"192.0.2.255"}`,  // line 2 admitted
205			`{"timestamp":"2026-01-02T00:00:00Z","action":"out-just-below","source_ip":"192.0.2.127"}`,    // line 3 dropped
206			`{"timestamp":"2026-01-02T00:00:00Z","action":"out-other-net","source_ip":"198.51.100.1"}`,    // line 4 dropped
207			`{"timestamp":"2026-01-02T00:00:00Z","action":"mapped-in","source_ip":"::ffff:192.0.2.200"}`,  // line 5 admitted
208			`{"timestamp":"2026-01-02T00:00:00Z","action":"mapped-out","source_ip":"::ffff:192.0.2.100"}`, // line 6 dropped
209			`{"timestamp":"2026-01-02T00:00:00Z","action":"compat-v6","source_ip":"::192.0.2.200"}`,       // line 7 dropped (IPv6)
210			`{"timestamp":"2026-01-02T00:00:00Z","action":"plain-v6","source_ip":"2001:db8::1"}`,          // line 8 dropped (IPv6)
211			`{"timestamp":"2026-01-02T00:00:00Z","action":"no-source"}`,                                   // line 9 dropped (absent)
212			`{"timestamp":"bad","action":"failed-in-net","source_ip":"192.0.2.200"}`,                      // line 10 failure
213			`{"timestamp":"bad","action":"failed-out-net","source_ip":"198.51.100.1"}`,                    // line 11 failure
214			`{"timestamp":"bad","action":"failed-absent"}`,                                                // line 12 failure
215			``, // line 13 blank
216			`{"timestamp":"2026-01-02T00:00:00Z","action":"tail","source_ip":"192.0.2.250"}`, // line 14 admitted
217		}, "\n") + "\n"
