337	
338		if result.exitCode != 2 {
339			t.Fatalf("a stdin read failure must exit 2, got %d (stderr: %q)", result.exitCode, result.stderr)
340		}
341		if result.stdout != "" {
342			t.Fatalf("no complete log line means no results on stdout, got %q", result.stdout)
343		}
344		if !strings.HasPrefix(result.stderr, "normalize: ") {
345			t.Fatalf("the read failure must be reported with the normalize: prefix, got %q", result.stderr)
346		}
347		if !strings.Contains(strings.ToLower(result.stderr), "read") {
348			t.Fatalf("the diagnostic must identify a read failure, got %q", result.stderr)
349		}
350	}
351	
352	// A log line with corrupted characters — invalid UTF-8 bytes or an unpaired
353	// \uXXXX surrogate escape anywhere in the object, including deep inside
354	// unmapped fields — is an ordinary per-line failure: one ok:false record with
355	// the physical line number and a reason that distinguishes the two defects,
356	// no event, valid lines around it still processed in order, exit status 1,
357	// and stderr empty. The failure records themselves must be valid UTF-8 JSON:
358	// corrupted input bytes are never echoed back into the output.
359	func TestNormalizeCLICorruptedCharactersExitOne(t *testing.T) {
360		input := []byte(`{"timestamp":"2026-01-02T00:00:00Z","action":"first"}` + "\n" +
361			`{"timestamp":"2026-01-02T00:00:00Z","action":"bad` + "\xff\xfe" + `"}` + "\n" +
362			`{"timestamp":"2026-01-02T00:00:00Z","action":"ok","extra":{"deep":["` + "\\uD800" + `"]}}` + "\n" +
363			`{"timestamp":"2026-01-02T00:00:02Z","action":"last"}` + "\n")
364	
365		result := runNormalizeCLI(t, bytes.NewReader(input))
366	
367		if result.exitCode != 1 {
368			t.Fatalf("corrupted log lines must set exit status 1, got %d (stderr: %q)", result.exitCode, result.stderr)
369		}
370		if result.stderr != "" {
371			t.Fatalf("per-line failures belong in result records, not stderr, got %q", result.stderr)
372		}
373		if !utf8.ValidString(result.stdout) {
374			t.Fatalf("stdout must be valid UTF-8 even for corrupted input, got %q", result.stdout)
375		}
376	
377		results := decodeStdoutResults(t, result.stdout)
378		if len(results) != 4 {
379			t.Fatalf("processing must continue past corrupted lines; expected 4 results, got %#v", results)
380		}
381		if results[0]["line"] != float64(1) || results[0]["ok"] != true {
382			t.Fatalf("the leading valid log must succeed on line 1: %#v", results[0])
383		}
384	
385		badUTF8 := results[1]
386		if badUTF8["line"] != float64(2) || badUTF8["ok"] != false {
387			t.Fatalf("the invalid-UTF-8 log must fail as line 2: %#v", badUTF8)
388		}
389		if _, exists := badUTF8["event"]; exists {
390			t.Fatalf("a corrupted line must not carry an event: %#v", badUTF8)
391		}
392		msg, _ := badUTF8["error"].(string)
393		if !strings.Contains(msg, "UTF-8") {
394			t.Fatalf("invalid bytes must be reported as UTF-8 corruption, got %q", msg)
395		}
396	
397		badEscape := results[2]
398		if badEscape["line"] != float64(3) || badEscape["ok"] != false {
399			t.Fatalf("the unpaired-escape log must fail as line 3: %#v", badEscape)
400		}
401		if _, exists := badEscape["event"]; exists {
402			t.Fatalf("a corrupted line must not carry an event: %#v", badEscape)
403		}
404		msg, _ = badEscape["error"].(string)
405		if !strings.Contains(msg, "surrogate") {
406			t.Fatalf("an unpaired escape deep in extra must be reported as a surrogate problem, got %q", msg)
407		}
408	
409		if results[3]["line"] != float64(4) || results[3]["ok"] != true {
410			t.Fatalf("the trailing valid log must still succeed on line 4: %#v", results[3])
411		}
412		if eventOf(t, results[3])["action"] != "last" {
413			t.Fatalf("line 4 event content mismatch: %#v", results[3])
414		}
415	}
416	
417	// A duplicate top-level key written with a unicode escape is the same failure
418	// as a literal repeated key. With one such line between legal logs (and a
419	// blank line shifting physical numbers), the CLI must emit per-line JSON
420	// results in order, keep the failure's line number with no event and a reason
421	// that names the field, and still exit 1: trailing valid lines never reset
422	// the status. An escape-only spelling of a standard field is a normal event.
423	func TestNormalizeCLIEscapedDuplicateKeyExitsOne(t *testing.T) {
424		dup := `{"timestamp":"2026-01-02T00:00:00Z","action":"first",` + escKey("action") + `:"second"}`
425		escapedOnly := `{` + escKey("timestamp") + `:"2026-01-02T08:04:05+08:00",` + escKey("action") + `:"ok"}`
426		input := `{"timestamp":"2026-01-02T00:00:00Z","action":"first"}` + "\n" +
427			dup + "\n" +
428			"  \n" +
429			`{"timestamp":"2026-01-02T00:00:02Z","action":"last"}` + "\n" +
430			escapedOnly
431	
432		result := runNormalizeCLI(t, strings.NewReader(input))
433	
434		if result.exitCode != 1 {
435			t.Fatalf("a duplicate-key line must set exit status 1 even with later valid logs, got %d (stderr: %q)",
436				result.exitCode, result.stderr)
437		}
438		if result.stderr != "" {
439			t.Fatalf("per-line failures belong in result records, not stderr, got %q", result.stderr)
440		}
441	
442		results := decodeStdoutResults(t, result.stdout)
443		if len(results) != 4 {
444			t.Fatalf("blank lines produce no output; expected 4 results, got %#v", results)
445		}
446		if results[0]["line"] != float64(1) || results[0]["ok"] != true {
447			t.Fatalf("leading valid log must succeed on line 1: %#v", results[0])
448		}
449		if eventOf(t, results[0])["action"] != "first" {
450			t.Fatalf("line 1 event content mismatch: %#v", results[0])
451		}
452	
453		bad := results[1]
454		if bad["line"] != float64(2) || bad["ok"] != false {
455			t.Fatalf("the escaped duplicate key must fail as line 2: %#v", bad)
456		}
457		if _, exists := bad["event"]; exists {
458			t.Fatalf("a failed line must not carry an event: %#v", bad)
459		}
460		message, ok := bad["error"].(string)
461		if !ok || message == "" {
462			t.Fatalf("the failed line must explain itself: %#v", bad)
463		}
464		if !strings.Contains(strings.ToLower(message), "duplicate") || !strings.Contains(message, "action") {
465			t.Fatalf("error must identify the duplicate action field, got %q", message)
466		}
467		if strings.Contains(strings.ToLower(message), "conflict") {
468			t.Fatalf("a decoded duplicate key must not be reported as an action conflict: %q", message)
469		}
470	
471		if results[2]["line"] != float64(4) || results[2]["ok"] != true {
472			t.Fatalf("the valid log after the blank line must succeed as line 4: %#v", results[2])
473		}
474		if eventOf(t, results[2])["action"] != "last" {
475			t.Fatalf("line 4 event content must survive in order: %#v", results[2])
476		}
477	
478		if results[3]["line"] != float64(5) || results[3]["ok"] != true {
479			t.Fatalf("an escape-only standard field spelling must succeed as line 5: %#v", results[3])
480		}
481		if eventOf(t, results[3])["timestamp"] != "2026-01-02T00:04:05Z" {
482			t.Fatalf("escaped-only names must normalize like literal names: %#v", results[3])
483		}
484	}
