			parsed, err := relayproof.ParseSourceCIDRFilter(value)
			if err != nil {
				return nil, fmt.Errorf("invalid %s value: %w", sourceCIDRFlag, err)
			}
			filter, specified = &parsed, true
		case strings.HasPrefix(arg, sourceCIDRFlag+"="):
